solution.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int s = 0;
        for (int i = 0; i < n; i++) {
            int x = in.nextInt();
            if (x < 0) {
                continue;
            }
            s += x;
        }
        System.out.println(s);
    }
}

